WITH valid AS (SELECT id, name, email, city, segment, signup_date, is_active, credit_limit, COALESCE(age, 0) age_filled FROM customers WHERE signup_date > DATE '2023-06-03' AND credit_limit BETWEEN 4600 AND 13000) SELECT *, SUM(age_filled) OVER (ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_age_filled, FIRST_VALUE(credit_limit, TRUE) OVER (ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_credit_limit, MIN(credit_limit) OVER (PARTITION BY city) city_min_credit_limit FROM valid;
